#include "eternity/game/character_core_save.hpp"
#include "eternity/game/creation.hpp"
#include "eternity/game/interface_save.hpp"
#include "eternity/game/inventory_save.hpp"
#include "eternity/game/point_items.hpp"
#include "eternity/game/quest_save.hpp"
#include "eternity/game/skill_save.hpp"
#include <iostream>

using namespace eternity;using namespace eternity::game;
namespace {
void require(bool value,const char* message) {if(!value) throw std::runtime_error(message);}
void put(net::Packet& p,std::uint64_t value,unsigned int count) {for(unsigned int i=0;i<count;++i) p.push_back(static_cast<std::uint8_t>(value>>(8*i)));}
net::Packet receipt_packet(std::uint16_t op,std::uint8_t source,std::uint8_t slot,std::uint64_t uid,std::uint16_t quality,std::uint8_t count,std::uint8_t make='U') {
    net::Packet p;put(p,op,2);put(p,9601,4);p.insert(p.end(),{source,1,slot});put(p,uid,8);put(p,5001,4);p.insert(p.end(),{5,1,count});put(p,quality,2);p.insert(p.end(),{1,2,3,4,5,6});const std::string craft="01020304050607080900";p.insert(p.end(),craft.begin(),craft.end());p.push_back(0);put(p,pack_world_time(std::chrono::sys_days{std::chrono::year{2024}/2/29}+std::chrono::hours{23}+std::chrono::minutes{59}+std::chrono::seconds{58}),4);p.push_back(make);return p;
}
}
int main(int argc,char** argv) {
    try {
        require(argc==2 && std::string_view(argv[1]).starts_with("Eternity_Test_Creation_"),"Point SQL test requires disposable catalog");const std::string catalog=argv[1],prefix="["+catalog+"].dbo.";storage::SqlServer db(storage::SqlServerConfig::from_environment());const auto definitions=Definitions::load(db);const auto rules=CreationRules::load(definitions);const auto time=std::chrono::sys_days{std::chrono::year{2024}/1/1};Characters characters(db,1,time,catalog);require(characters.save_country(9601,0,true),"Cannot initialize point fixture account");auto draft=rules.prepare({0,0,2,0,0,0,0,0,"PointHero"},0);draft.items.clear();const auto created=characters.create(9601,"point_user",draft,time);require(created.result==0,"Cannot create point fixture character");const auto cid=std::to_string(created.character_id);
        db.query("INSERT "+prefix+"Users_Product(UserUID,Slot,ItemID,ItemCount,ProductCode,OrderNumber,VerifyCode,BuyDate) VALUES(9601,0,5001,10,'receipt_product',123,456,'20240102'),(9601,239,16001,0,'last_product',124,457,'20240103'),(9602,0,30001,5,'other_product',125,458,'20240104'); INSERT "+prefix+"UserStoredPointItems(UserUID,Slot,ItemID,ItemCount) VALUES(9601,1,5001,3),(9601,239,16001,0),(9602,1,30001,5);");
        PlayerCore initial;initial.user_id=9601;initial.character=draft.character;initial.character.id=created.character_id;initial.money=77;InventoryReplicaPool pool;CharacterReplica cache(initial,pool);PointItemStore receipts(db,1,catalog);receipts.load_products(cache.points());const auto stored=db.query("EXEC "+prefix+"usp_Read_User_StoredPointItems 9601;");PlayerSnapshot loaded;loaded.core=initial;loaded.point_items=decode_point_items(stored[0]);require(cache.points().load(loaded),"Cannot load typed stored points");require(cache.points().products()[0].count==10 && cache.points().products()[239].type==16 && cache.points().stored().size()==2 && cache.points().stored()[1].second.receipt.count==0,"Original product/point load differs");
        auto product=receipt_packet(0x710,0,0,UINT64_MAX-10,77,10);auto point=receipt_packet(0xe05,1,1,UINT64_MAX-11,5001,3);require(cache.apply(product)==InventoryReplicaResult::applied && cache.apply(point)==InventoryReplicaResult::applied,"Cannot receive product/point items");require(cache.points().products()[0].count==0 && cache.points().products()[0].save_type==3 && cache.points().stored()[0].second.save_type==3 && cache.inventory().inventory()[0].save_type==0,"Receipt did not leave authoritative SQL work in its source cache");
        bool rejected=false;try{receipts.save_in_transaction(cache.points(),created.character_id);}catch(const std::logic_error&){rejected=true;}require(rejected,"Point save ran outside character transaction");
        CharacterCoreStore core(db,catalog);InventoryStore items(db,1,catalog);SkillStore skills(db,catalog);QuestStore quests(db,catalog);InterfaceStore ui(db,catalog);MarketStore market(db,catalog);
        const auto save=[&](){core.save_in_transaction(cache);receipts.save_in_transaction(cache.points(),created.character_id);items.save_in_transaction(cache.inventory(),created.character_id);skills.save_in_transaction(cache.skills(),created.character_id);quests.save_in_transaction(cache.quests(),created.character_id);ui.save_in_transaction(cache.interface(),created.character_id,false);market.save_in_transaction(cache.market(),created.character_id);};
        const auto ack=[&](){cache.core_save_success();cache.inventory().inventory_save_success();cache.skills().save_success();cache.quests().save_success();cache.interface().save_success();cache.points().point_save_success();};
        PlayerItem bad;bad.uid=0x7777000000000900ULL;bad.id=2147483000;bad.type=5;bad.type_id=1;bad.bag=5;bad.slot=23;bad.count=1;bad.made_at=pack_world_time(time);bad.make_type="U";require(cache.inventory().load(bad,false,1),"Cannot seed later inventory failure");
        db.begin();bool failed=false;try{save();}catch(const std::runtime_error&){failed=true;}require(failed,"Later inventory error did not fail complete receipt save");db.rollback();
        auto rows=db.query("SELECT COUNT(*) FROM "+prefix+"CharItems WHERE CharID="+cid+"; SELECT COUNT(*) FROM "+prefix+"ProductLog WHERE UserUID=9601; SELECT COUNT(*) FROM "+prefix+"Users_Product WHERE UserUID=9601; SELECT COUNT(*) FROM "+prefix+"UserStoredPointItems WHERE UserUID=9601; SELECT Money FROM "+prefix+"Chars WHERE CharID="+cid+";");require(rows[0].rows[0][0]==storage::Cell{"0"} && rows[1].rows[0][0]==storage::Cell{"0"} && rows[2].rows[0][0]==storage::Cell{"2"} && rows[3].rows[0][0]==storage::Cell{"2"} && rows[4].rows[0][0]==storage::Cell{"0"},"Receipt procedures escaped the caller transaction");require(cache.points().products()[0].save_type==3 && cache.points().stored()[0].second.save_type==3,"Failed save acknowledged a receipt");
        net::Packet drop{2,7};put(drop,9601,4);drop.insert(drop.end(),{5,23,255});require(cache.apply(drop)==InventoryReplicaResult::applied,"Cannot remove rejected new item");
        db.begin();save();const auto depth=db.query("SELECT @@TRANCOUNT;");require(depth[0].rows[0][0]==storage::Cell{"1"},"Receipt procedures changed caller transaction depth");db.commit();ack();
        rows=db.query("SELECT ItemUID,Bag,Slot,Quality,Gem1,Gem6,Craftname,[Count],CONVERT(varchar(19),MakeTime,120),MakeType FROM "+prefix+"CharItems WHERE CharID="+cid+" ORDER BY Slot; SELECT ProductCode,OrderNumber,VerifyCode,CONVERT(varchar(10),BuyDate,120) FROM "+prefix+"ProductLog WHERE UserUID=9601; SELECT Slot FROM "+prefix+"Users_Product WHERE UserUID=9601; SELECT Slot FROM "+prefix+"UserStoredPointItems WHERE UserUID=9601;");
        require(rows[0].rows==std::vector<storage::Row>{{storage::Cell{"-11"},storage::Cell{"1"},storage::Cell{"0"},storage::Cell{"77"},storage::Cell{"0"},storage::Cell{"0"},storage::Cell{""},storage::Cell{"10"},storage::Cell{"2024-02-29 23:59:58"},storage::Cell{"U"}},{storage::Cell{"-12"},storage::Cell{"1"},storage::Cell{"1"},storage::Cell{"0"},storage::Cell{"0"},storage::Cell{"0"},storage::Cell{""},storage::Cell{"3"},storage::Cell{"2024-02-29 23:59:58"},storage::Cell{"U"}}},"Receipt item SQL widths/default gems/craft/quality changed");require(rows[1].rows==std::vector<storage::Row>{{storage::Cell{"receipt_product"},storage::Cell{"123"},storage::Cell{"456"},storage::Cell{"2024-01-02"}}} && rows[2].rows==std::vector<storage::Row>{{storage::Cell{"239"}}} && rows[3].rows==std::vector<storage::Row>{{storage::Cell{"239"}}},"Receipt metadata or source deletion changed");require(cache.points().products()[0].save_type==0 && cache.points().stored().size()==1 && cache.points().stored()[0].first==239,"Original full ACK product reset/point recycling changed");
        // Acknowledged receipts must not be delivered again. A later ordinary
        // count update uses the shared inventory row created by the receipt phase.
        net::Packet count{0x17,6};put(count,9601,4);count.insert(count.end(),{1,0,7});require(cache.apply(count)==InventoryReplicaResult::applied,"Cannot update delivered inventory row");
        db.begin();save();db.commit();ack();
        rows=db.query("SELECT [Count],Gem1,Craftname FROM "+prefix+"CharItems WHERE CharID="+cid+" AND Slot=0;");require(rows[0].rows==std::vector<storage::Row>{{storage::Cell{"7"},storage::Cell{"1"},storage::Cell{"01020304050607080900"}}},"Ordinary inventory updates did not share the delivered item");
        rows=db.query("SELECT COUNT(*) FROM "+prefix+"ProductLog WHERE UserUID=9601; SELECT COUNT(*) FROM "+prefix+"Users_Product WHERE UserUID=9602; SELECT COUNT(*) FROM "+prefix+"UserStoredPointItems WHERE UserUID=9602;");require(rows[0].rows[0][0]==storage::Cell{"1"} && rows[1].rows[0][0]==storage::Cell{"1"} && rows[2].rows[0][0]==storage::Cell{"1"},"Repeated product save duplicated logs or reached another account");
        // A stale point snapshot whose source disappeared must not insert a free
        // inventory row: the original zero-delete branch rolls back and returns -1.
        CharacterReplica stale(initial,pool);const std::array<PlayerPointItem,1> old{{{1,5001,3}}};stale.points().load_stored(old);require(stale.apply(receipt_packet(0xe05,1,2,0x7777000000000910ULL,1,3))==InventoryReplicaResult::applied,"Cannot stage stale point receipt");db.begin();failed=false;try{receipts.save_in_transaction(stale.points(),created.character_id);}catch(const std::runtime_error&){failed=true;}require(failed,"Missing stored source was accepted");db.rollback();rows=db.query("SELECT COUNT(*) FROM "+prefix+"CharItems WHERE CharID="+cid+" AND Slot=2;");require(rows[0].rows[0][0]==storage::Cell{"0"} && stale.points().stored()[0].second.save_type==3,"Missing-source rollback retained free item or acknowledged cache");
        CharacterReplica malformed(initial,pool);receipts.load_products(malformed.points());require(malformed.apply(receipt_packet(0x710,239,3,0x7777000000000911ULL,1,1,0))==InventoryReplicaResult::applied,"Cannot stage zero-MakeType receipt");db.begin();failed=false;try{receipts.save_in_transaction(malformed.points(),created.character_id);}catch(const std::runtime_error&){failed=true;}db.rollback();require(failed,"Bound empty MakeType repaired the original truncated SQL literal");
        std::cout<<"Original product/stored-point SQL passed: linked-table fixture, distributed transaction rollback/retry, metadata, receipt defaults, product ACK, point recycling and missing-source failure\n";
    }catch(const std::exception& error) {std::cerr<<error.what()<<'\n';return 1;}
}
